    static let openings: [DuaMood: (english: String, arabic: String)] = [
        .angry: (english: "Anger is a fire. Here is water.", arabic: "الغضب نار، وهذه ماء."),
        .anxious: (english: "Your heart is racing. Let it slow down here.", arabic: "قلبك يتسارع. دعه يهدأ هنا."),
        .urgeToSin: (english: "The pull is real. So is the way out.", arabic: "الجذب حقيقي، والمخرج حقيقي أيضًا."),
        .confident: (english: "Good. Now anchor it to the One who gave it.", arabic: "جميل. اربطها الآن بمن وهبك إياها."),
        .confused: (english: "You don’t need clarity yet. You need Him.", arabic: "لا تحتاج الوضوح الآن، بل تحتاجه هو."),
        .content: (english: "This calm is a gift. Say thank you for it.", arabic: "هذا السكون نعمة، فاشكرها."),
        .depressed: (english: "It’s heavy, and it’s dark. You are not alone in it.", arabic: "ثقيل ومظلم، لكنك لست وحدك فيه."),
        .doubtful: (english: "Doubt is a question, not a verdict.", arabic: "الشك سؤال، لا حكم."),
        .grateful: (english: "Gratitude keeps blessings close.", arabic: "الشكر يُبقي النعم قريبة."),
        .greedy: (english: "What you chase is His to give. Ask instead.", arabic: "ما تلاحقه بيده. اسأله بدل الملاحقة."),
        .guilty: (english: "Guilt means your heart still works. Bring it back.", arabic: "الشعور بالذنب دليل أن قلبك حي. عُد به."),
        .happy: (english: "Joy is from Him. Send it back up as praise.", arabic: "الفرح منه، فأعده إليه حمدًا."),
        .hurt: (english: "Someone hurt you. He saw it.", arabic: "أحدهم آذاك، وهو رأى ذلك."),
        .indecisive: (english: "You can’t see every road. He can.", arabic: "لا ترى كل الطرق، وهو يراها."),
        .hypocritical: (english: "Fearing hypocrisy is a sign of sincerity.", arabic: "الخوف من النفاق علامة على الصدق."),
        .jealous: (english: "What they have was written for them. Ask for yours.", arabic: "ما عندهم كُتب لهم. اسأل ما كُتب لك."),
        .lazy: (english: "Small words, said now, are enough to begin.", arabic: "كلمات يسيرة تقولها الآن تكفي للبدء."),
        .lonely: (english: "Alone in a room, never alone in the world.", arabic: "وحيد في غرفة، لا وحيد في العالم."),
        .lost: (english: "The way isn’t clear yet. Ask the One who knows it.", arabic: "الطريق غير واضح بعد. اسأل من يعلمه."),
        .nervous: (english: "Breathe. Then hand the outcome over.", arabic: "تنفس، ثم سلّم النتيجة."),
        .overwhelmed: (english: "You were never meant to carry all of it.", arabic: "لم تُخلق لتحمل كل هذا."),
        .regret: (english: "What’s done is done. What’s next is still yours.", arabic: "ما مضى مضى، وما يأتي ما زال بيدك."),
        .sad: (english: "Sadness is allowed here. So is hope.", arabic: "الحزن مسموح هنا، والأمل كذلك."),
        .scared: (english: "Fear shrinks when you name Who is bigger.", arabic: "الخوف يصغر حين تذكر من هو أكبر."),
        .suicidal: (english: "You matter. Please reach out to someone now, and stay with these words.", arabic: "أنت مهم. تواصل مع أحد الآن، وابقَ مع هذه الكلمات."),
        .tired: (english: "Rest is not failure. Ask for strength.", arabic: "الراحة ليست فشلًا. اطلب القوة."),
        .unloved: (english: "The One who made you loves you. Start there.", arabic: "من خلقك يحبك. ابدأ من هنا."),
        .weak: (english: "Weakness is where His strength enters.", arabic: "من الضعف يدخل عونه."),
        .bored: (english: "Emptiness is space. Fill it with remembrance.", arabic: "الفراغ مساحة، فاملأها ذكرًا."),
        .impatient: (english: "His timing has never been late.", arabic: "توقيته لم يتأخر قط."),
        .hopeful: (english: "Hope is a form of trust. Keep it alive.", arabic: "الأمل صورة من الثقة، فأبقه حيًّا."),
        .grieving: (english: "Loss is real. So is the reunion.", arabic: "الفقد حقيقي، واللقاء حقيقي أيضًا."),
        .seekingForgiveness: (english: "The door back is open. It always was.", arabic: "باب العودة مفتوح، وما زال كذلك."),
    ]

    static let namesNoteEnglish = "This is the well-known enumeration. The hadith affirming ninety-nine names is in Sahih al-Bukhari 2736 and Sahih Muslim 2677 without a list; the listed order follows Jami‘ at-Tirmidhi 3507, whose enumeration some scholars grade weak."
    static let namesNoteArabic = "هذه هي القائمة المشهورة. ورد حديث الأسماء التسعة والتسعين في البخاري ٢٧٣٦ ومسلم ٢٦٧٧ دون سرد، وترتيبها هنا من جامع الترمذي ٣٥٠٧ الذي ضعّف بعض العلماء سرده."
    static let names: [DivineName] = names1 + names2 + names3 + names4 + names5
    private static let names1: [DivineName] = [
        DivineName(id: "ar-rahman", arabic: "الرَّحْمَنُ", transliteration: "Ar-Rahman", meaning: "The Most Merciful", verse: "1:3", meaningArabic: "واسع الرحمة لكل خلقه", reflectionEnglish: "His mercy reaches you before you ask for it.", reflectionArabic: "رحمته تسبقك قبل أن تطلبها."),
        DivineName(id: "ar-rahim", arabic: "الرَّحِيمُ", transliteration: "Ar-Rahim", meaning: "The Especially Merciful", verse: "1:3", meaningArabic: "الرحيم بعباده المؤمنين", reflectionEnglish: "A mercy kept for those who turn to Him.", reflectionArabic: "رحمة خاصة بمن أقبل عليه."),
        DivineName(id: "al-malik", arabic: "الْمَلِكُ", transliteration: "Al-Malik", meaning: "The King", verse: "59:23", meaningArabic: "المالك لكل شيء", reflectionEnglish: "Everything you fear is under His rule.", reflectionArabic: "كل ما تخشاه تحت ملكه."),
        DivineName(id: "al-quddus", arabic: "الْقُدُّوسُ", transliteration: "Al-Quddus", meaning: "The Most Holy", verse: "59:23", meaningArabic: "المنزّه عن كل نقص", reflectionEnglish: "Free of every flaw you find in yourself.", reflectionArabic: "منزّه عن كل نقص تراه في نفسك."),
        DivineName(id: "as-salam", arabic: "السَّلَامُ", transliteration: "As-Salam", meaning: "The Source of Peace", verse: "59:23", meaningArabic: "السالم من كل عيب، واهب السلام", reflectionEnglish: "Peace comes from Him, not from circumstances.", reflectionArabic: "السلام منه، لا من الظروف."),
        DivineName(id: "al-mumin", arabic: "الْمُؤْمِنُ", transliteration: "Al-Mu’min", meaning: "The Giver of Security", verse: "59:23", meaningArabic: "واهب الأمن والأمان", reflectionEnglish: "When nothing feels safe, He is safety itself.", reflectionArabic: "حين لا تجد أمانًا، هو الأمن نفسه."),
        DivineName(id: "al-muhaymin", arabic: "الْمُهَيْمِنُ", transliteration: "Al-Muhaymin", meaning: "The Guardian", verse: "59:23", meaningArabic: "الرقيب الحافظ على كل شيء", reflectionEnglish: "Nothing about you goes unwatched or unheld.", reflectionArabic: "لا شيء فيك يغيب عن رعايته."),
        DivineName(id: "al-aziz", arabic: "الْعَزِيزُ", transliteration: "Al-‘Aziz", meaning: "The Almighty", verse: "59:23", meaningArabic: "الغالب الذي لا يُغلب", reflectionEnglish: "His strength is never in short supply.", reflectionArabic: "عزّته لا تنفد أبدًا."),
        DivineName(id: "al-jabbar", arabic: "الْجَبَّارُ", transliteration: "Al-Jabbar", meaning: "The Compeller, the Restorer", verse: "59:23", meaningArabic: "القاهر الذي يجبر الكسير", reflectionEnglish: "He mends what is broken, including hearts.", reflectionArabic: "يجبر الكسر، والقلوب منه."),
        DivineName(id: "al-mutakabbir", arabic: "الْمُتَكَبِّرُ", transliteration: "Al-Mutakabbir", meaning: "The Supreme", verse: "59:23", meaningArabic: "المتعالي عن صفات الخلق", reflectionEnglish: "Greatness belongs to Him alone; you can rest.", reflectionArabic: "الكبرياء له وحده، فاسترح."),
        DivineName(id: "al-khaliq", arabic: "الْخَالِقُ", transliteration: "Al-Khaliq", meaning: "The Creator", verse: "59:24", meaningArabic: "خالق كل شيء", reflectionEnglish: "He made you on purpose.", reflectionArabic: "خلقك على قصد وحكمة."),
        DivineName(id: "al-bari", arabic: "الْبَارِئُ", transliteration: "Al-Bari’", meaning: "The Originator", verse: "59:24", meaningArabic: "الموجد من العدم", reflectionEnglish: "He brought you from nothing; He can bring ease from nothing.", reflectionArabic: "أوجدك من العدم، ويوجد الفرج من العدم."),
        DivineName(id: "al-musawwir", arabic: "الْمُصَوِّرُ", transliteration: "Al-Musawwir", meaning: "The Fashioner", verse: "59:24", meaningArabic: "الذي أعطى كل شيء صورته", reflectionEnglish: "Your shape, your voice, your story: His design.", reflectionArabic: "صورتك وصوتك وقصتك من تصويره."),
        DivineName(id: "al-ghaffar", arabic: "الْغَفَّارُ", transliteration: "Al-Ghaffar", meaning: "The Ever-Forgiving", verse: "20:82", meaningArabic: "كثير المغفرة", reflectionEnglish: "He forgives again, and again, and again.", reflectionArabic: "يغفر مرة بعد مرة بعد مرة."),
        DivineName(id: "al-qahhar", arabic: "الْقَهَّارُ", transliteration: "Al-Qahhar", meaning: "The Subduer", verse: "12:39", meaningArabic: "القاهر فوق عباده", reflectionEnglish: "Every tyrant, every worry, is beneath Him.", reflectionArabic: "كل جبّار وكل همّ دون قهره."),
        DivineName(id: "al-wahhab", arabic: "الْوَهَّابُ", transliteration: "Al-Wahhab", meaning: "The Bestower", verse: "3:8", meaningArabic: "كثير العطاء بلا عوض", reflectionEnglish: "He gives without being owed.", reflectionArabic: "يعطي بلا مقابل."),
        DivineName(id: "ar-razzaq", arabic: "الرَّزَّاقُ", transliteration: "Ar-Razzaq", meaning: "The Provider", verse: "51:58", meaningArabic: "الذي يرزق كل مخلوق", reflectionEnglish: "Your provision is written and on its way.", reflectionArabic: "رزقك مكتوب وآتٍ."),
        DivineName(id: "al-fattah", arabic: "الْفَتَّاحُ", transliteration: "Al-Fattah", meaning: "The Opener", verse: "34:26", meaningArabic: "الذي يفتح أبواب الخير والفرج", reflectionEnglish: "Closed doors are His to open.", reflectionArabic: "الأبواب المغلقة بيده تُفتح."),
        DivineName(id: "al-alim", arabic: "الْعَلِيمُ", transliteration: "Al-‘Alim", meaning: "The All-Knowing", verse: "2:158", meaningArabic: "العالم بكل شيء", reflectionEnglish: "He knows what you cannot put into words.", reflectionArabic: "يعلم ما تعجز عن قوله."),
        DivineName(id: "al-qabid", arabic: "الْقَابِضُ", transliteration: "Al-Qabid", meaning: "The Withholder", verse: "2:245", meaningArabic: "الذي يقبض الرزق والأرواح بحكمة", reflectionEnglish: "What is held back is held back with wisdom.", reflectionArabic: "ما قُبض عنك قُبض بحكمة."),
    ]
    private static let names2: [DivineName] = [
        DivineName(id: "al-basit", arabic: "الْبَاسِطُ", transliteration: "Al-Basit", meaning: "The Extender", verse: "2:245", meaningArabic: "الذي يبسط الرزق والرحمة", reflectionEnglish: "Ease expands from His hand.", reflectionArabic: "السعة تنبسط من يده."),
        DivineName(id: "al-khafid", arabic: "الْخَافِضُ", transliteration: "Al-Khafid", meaning: "The Abaser", verse: "56:3", meaningArabic: "الذي يخفض الجبابرة", reflectionEnglish: "No one stays high without His leave.", reflectionArabic: "لا يبقى مرتفع إلا بإذنه."),
        DivineName(id: "ar-rafi", arabic: "الرَّافِعُ", transliteration: "Ar-Rafi‘", meaning: "The Exalter", verse: "6:83", meaningArabic: "الذي يرفع من يشاء", reflectionEnglish: "He can raise you when the world looks down on you.", reflectionArabic: "يرفعك حين ينظر إليك الناس بازدراء."),
        DivineName(id: "al-muizz", arabic: "الْمُعِزُّ", transliteration: "Al-Mu‘izz", meaning: "The Honourer", verse: "3:26", meaningArabic: "الذي يمنح العزة", reflectionEnglish: "Real honour is given by Him, not by people.", reflectionArabic: "العزة الحقيقية منه لا من الناس."),
        DivineName(id: "al-mudhill", arabic: "الْمُذِلُّ", transliteration: "Al-Mudhill", meaning: "The Humbler", verse: "3:26", meaningArabic: "الذي يذل من يشاء", reflectionEnglish: "Arrogance never lasts before Him.", reflectionArabic: "لا يدوم كِبر أمامه."),
        DivineName(id: "as-sami", arabic: "السَّمِيعُ", transliteration: "As-Sami‘", meaning: "The All-Hearing", verse: "2:127", meaningArabic: "السامع لكل صوت", reflectionEnglish: "Your whisper reaches Him as clearly as a shout.", reflectionArabic: "همسك يبلغه كما يبلغه صراخك."),
        DivineName(id: "al-basir", arabic: "الْبَصِيرُ", transliteration: "Al-Basir", meaning: "The All-Seeing", verse: "4:58", meaningArabic: "المبصر لكل شيء", reflectionEnglish: "Your unseen effort is fully seen.", reflectionArabic: "جهدك الخفي مرئي عنده."),
        DivineName(id: "al-hakam", arabic: "الْحَكَمُ", transliteration: "Al-Hakam", meaning: "The Judge", verse: "22:69", meaningArabic: "الذي يحكم بين خلقه بالعدل", reflectionEnglish: "Injustice against you will not be the final word.", reflectionArabic: "الظلم الذي أصابك ليس الكلمة الأخيرة."),
        DivineName(id: "al-adl", arabic: "الْعَدْلُ", transliteration: "Al-‘Adl", meaning: "The Just", verse: "6:115", meaningArabic: "العادل في حكمه وقضائه", reflectionEnglish: "He is never unfair, even when life feels so.", reflectionArabic: "لا يظلم أبدًا وإن بدت الحياة ظالمة."),
        DivineName(id: "al-latif", arabic: "اللَّطِيفُ", transliteration: "Al-Latif", meaning: "The Subtle, the Kind", verse: "6:103", meaningArabic: "الرفيق بعباده في خفاء", reflectionEnglish: "He is gentle with you in ways you will only see later.", reflectionArabic: "يلطف بك بطرق لا تراها إلا لاحقًا."),
        DivineName(id: "al-khabir", arabic: "الْخَبِيرُ", transliteration: "Al-Khabir", meaning: "The All-Aware", verse: "6:18", meaningArabic: "العالم بدقائق الأمور", reflectionEnglish: "He knows the details that no one else notices.", reflectionArabic: "يعلم التفاصيل التي لا يلحظها أحد."),
        DivineName(id: "al-halim", arabic: "الْحَلِيمُ", transliteration: "Al-Halim", meaning: "The Forbearing", verse: "2:235", meaningArabic: "الذي لا يعجل بالعقوبة", reflectionEnglish: "He is patient with you; be patient with yourself.", reflectionArabic: "يحلم عليك، فارفق بنفسك."),
        DivineName(id: "al-azim", arabic: "الْعَظِيمُ", transliteration: "Al-‘Azim", meaning: "The Magnificent", verse: "2:255", meaningArabic: "العظيم في ذاته وصفاته", reflectionEnglish: "Your problem is small next to His greatness.", reflectionArabic: "مشكلتك صغيرة أمام عظمته."),
        DivineName(id: "al-ghafur", arabic: "الْغَفُورُ", transliteration: "Al-Ghafur", meaning: "The All-Forgiving", verse: "2:173", meaningArabic: "الذي يستر الذنوب ويمحوها", reflectionEnglish: "No sin is too large for His forgiveness.", reflectionArabic: "لا ذنب أكبر من مغفرته."),
        DivineName(id: "ash-shakur", arabic: "الشَّكُورُ", transliteration: "Ash-Shakur", meaning: "The Appreciative", verse: "35:30", meaningArabic: "الذي يجازي القليل بالكثير", reflectionEnglish: "He rewards even the smallest sincere act.", reflectionArabic: "يجازي أصغر عمل صادق."),
        DivineName(id: "al-ali", arabic: "الْعَلِيُّ", transliteration: "Al-‘Ali", meaning: "The Most High", verse: "2:255", meaningArabic: "العالي فوق كل شيء", reflectionEnglish: "Above every power that frightens you.", reflectionArabic: "فوق كل قوة تخيفك."),
        DivineName(id: "al-kabir", arabic: "الْكَبِيرُ", transliteration: "Al-Kabir", meaning: "The Most Great", verse: "13:9", meaningArabic: "الكبير الذي لا أكبر منه", reflectionEnglish: "Allahu akbar: greater than whatever this is.", reflectionArabic: "الله أكبر من كل ما تواجهه."),
        DivineName(id: "al-hafiz", arabic: "الْحَفِيظُ", transliteration: "Al-Hafiz", meaning: "The Preserver", verse: "11:57", meaningArabic: "الحافظ لكل شيء", reflectionEnglish: "You are kept, even when you cannot keep yourself.", reflectionArabic: "أنت محفوظ وإن عجزت عن حفظ نفسك."),
        DivineName(id: "al-muqit", arabic: "الْمُقِيتُ", transliteration: "Al-Muqit", meaning: "The Sustainer", verse: "4:85", meaningArabic: "الذي يقوت كل حي", reflectionEnglish: "What you need to get through today is already provided.", reflectionArabic: "ما تحتاجه ليومك مقدَّر لك."),
        DivineName(id: "al-hasib", arabic: "الْحَسِيبُ", transliteration: "Al-Hasib", meaning: "The Reckoner", verse: "4:6", meaningArabic: "الكافي والمحاسب", reflectionEnglish: "He is enough for you, and He keeps the account.", reflectionArabic: "هو حسبك، وهو المحاسب."),
    ]
    private static let names3: [DivineName] = [
        DivineName(id: "al-jalil", arabic: "الْجَلِيلُ", transliteration: "Al-Jalil", meaning: "The Majestic", verse: "55:27", meaningArabic: "صاحب الجلال والعظمة", reflectionEnglish: "Majesty that makes everything else small.", reflectionArabic: "جلال يصغر أمامه كل شيء."),
        DivineName(id: "al-karim", arabic: "الْكَرِيمُ", transliteration: "Al-Karim", meaning: "The Generous", verse: "27:40", meaningArabic: "الكريم الذي يعطي بلا حساب", reflectionEnglish: "He gives more than you asked, better than you asked.", reflectionArabic: "يعطي أكثر مما سألت وأحسن مما سألت."),
        DivineName(id: "ar-raqib", arabic: "الرَّقِيبُ", transliteration: "Ar-Raqib", meaning: "The Watchful", verse: "4:1", meaningArabic: "المطلع على كل شيء", reflectionEnglish: "Watched over, not spied on.", reflectionArabic: "مراقَب برعاية لا بتربص."),
        DivineName(id: "al-mujib", arabic: "الْمُجِيبُ", transliteration: "Al-Mujib", meaning: "The Responsive", verse: "11:61", meaningArabic: "الذي يجيب الداعي", reflectionEnglish: "Every du’a is answered, in one way or another.", reflectionArabic: "كل دعاء مجاب بوجه من الوجوه."),
        DivineName(id: "al-wasi", arabic: "الْوَاسِعُ", transliteration: "Al-Wasi‘", meaning: "The All-Encompassing", verse: "2:268", meaningArabic: "الواسع في رحمته وعلمه", reflectionEnglish: "His mercy is wider than your mistakes.", reflectionArabic: "رحمته أوسع من أخطائك."),
        DivineName(id: "al-hakim", arabic: "الْحَكِيمُ", transliteration: "Al-Hakim", meaning: "The All-Wise", verse: "2:129", meaningArabic: "صاحب الحكمة التامة", reflectionEnglish: "There is wisdom in this, even if you cannot see it yet.", reflectionArabic: "في هذا حكمة وإن لم ترها بعد."),
        DivineName(id: "al-wadud", arabic: "الْوَدُودُ", transliteration: "Al-Wadud", meaning: "The Most Loving", verse: "11:90", meaningArabic: "المحب لعباده الصالحين", reflectionEnglish: "You are loved by the One who made you.", reflectionArabic: "محبوب عند من خلقك."),
        DivineName(id: "al-majid", arabic: "الْمَجِيدُ", transliteration: "Al-Majid", meaning: "The Most Glorious", verse: "11:73", meaningArabic: "الواسع الكرم والمجد", reflectionEnglish: "Glory that lifts whoever turns to Him.", reflectionArabic: "مجد يرفع من أقبل عليه."),
        DivineName(id: "al-baith", arabic: "الْبَاعِثُ", transliteration: "Al-Ba‘ith", meaning: "The Resurrector", verse: "22:7", meaningArabic: "الذي يبعث الخلق يوم القيامة", reflectionEnglish: "This is not the end of the story.", reflectionArabic: "ليست هذه نهاية القصة."),
        DivineName(id: "ash-shahid", arabic: "الشَّهِيدُ", transliteration: "Ash-Shahid", meaning: "The Witness", verse: "4:79", meaningArabic: "الشاهد على كل شيء", reflectionEnglish: "He witnessed what was done to you.", reflectionArabic: "شهد ما أصابك."),
        DivineName(id: "al-haqq", arabic: "الْحَقُّ", transliteration: "Al-Haqq", meaning: "The Truth", verse: "22:6", meaningArabic: "الحق الثابت الذي لا يزول", reflectionEnglish: "When everything is uncertain, He is certain.", reflectionArabic: "حين يتزعزع كل شيء، هو الثابت."),
        DivineName(id: "al-wakil", arabic: "الْوَكِيلُ", transliteration: "Al-Wakil", meaning: "The Trustee", verse: "3:173", meaningArabic: "الذي يُتوكل عليه", reflectionEnglish: "Hand it to Him and let your shoulders drop.", reflectionArabic: "سلّمه الأمر ودع كتفيك يرتاحان."),
        DivineName(id: "al-qawiyy", arabic: "الْقَوِيُّ", transliteration: "Al-Qawiyy", meaning: "The All-Strong", verse: "22:40", meaningArabic: "صاحب القوة الكاملة", reflectionEnglish: "Borrow your strength from His.", reflectionArabic: "استمد قوتك من قوته."),
        DivineName(id: "al-matin", arabic: "الْمَتِينُ", transliteration: "Al-Matin", meaning: "The Firm", verse: "51:58", meaningArabic: "الشديد القوي الذي لا يتزعزع", reflectionEnglish: "He does not tire of holding you.", reflectionArabic: "لا يكلّ من حملك."),
        DivineName(id: "al-waliyy", arabic: "الْوَلِيُّ", transliteration: "Al-Waliyy", meaning: "The Protecting Friend", verse: "4:45", meaningArabic: "الناصر والمتولي لعباده", reflectionEnglish: "You have an ally who never leaves.", reflectionArabic: "لك وليّ لا يتخلى عنك."),
        DivineName(id: "al-hamid", arabic: "الْحَمِيدُ", transliteration: "Al-Hamid", meaning: "The Praiseworthy", verse: "14:8", meaningArabic: "المستحق للحمد كله", reflectionEnglish: "Worthy of praise in hardship and in ease.", reflectionArabic: "يستحق الحمد في الشدة والرخاء."),
        DivineName(id: "al-muhsi", arabic: "الْمُحْصِي", transliteration: "Al-Muhsi", meaning: "The Enumerator", verse: "72:28", meaningArabic: "الذي أحصى كل شيء عددًا", reflectionEnglish: "Not one of your tears is uncounted.", reflectionArabic: "ولا دمعة منك إلا محصاة."),
        DivineName(id: "al-mubdi", arabic: "الْمُبْدِئُ", transliteration: "Al-Mubdi’", meaning: "The Initiator", verse: "10:34", meaningArabic: "الذي بدأ الخلق", reflectionEnglish: "Every beginning starts with Him.", reflectionArabic: "كل بداية تبدأ به."),
        DivineName(id: "al-muid", arabic: "الْمُعِيدُ", transliteration: "Al-Mu‘id", meaning: "The Restorer", verse: "10:34", meaningArabic: "الذي يعيد الخلق بعد فنائه", reflectionEnglish: "He can bring back what you thought was lost.", reflectionArabic: "يعيد ما ظننته ضاع."),
        DivineName(id: "al-muhyi", arabic: "الْمُحْيِي", transliteration: "Al-Muhyi", meaning: "The Giver of Life", verse: "30:50", meaningArabic: "الذي يحيي الموتى والقلوب", reflectionEnglish: "He revives dead land and tired hearts.", reflectionArabic: "يحيي الأرض الميتة والقلوب المتعبة."),
    ]
    private static let names4: [DivineName] = [
        DivineName(id: "al-mumit", arabic: "الْمُمِيتُ", transliteration: "Al-Mumit", meaning: "The Bringer of Death", verse: "3:156", meaningArabic: "الذي يميت الأحياء", reflectionEnglish: "Everything ends except Him; live for what lasts.", reflectionArabic: "كل شيء ينتهي إلا هو؛ فاعمل لما يبقى."),
        DivineName(id: "al-hayy", arabic: "الْحَيُّ", transliteration: "Al-Hayy", meaning: "The Ever-Living", verse: "2:255", meaningArabic: "الحي الذي لا يموت", reflectionEnglish: "Your source of help never sleeps.", reflectionArabic: "من تستعين به لا ينام."),
        DivineName(id: "al-qayyum", arabic: "الْقَيُّومُ", transliteration: "Al-Qayyum", meaning: "The Sustainer of All", verse: "2:255", meaningArabic: "القائم بنفسه، المقيم لغيره", reflectionEnglish: "He holds everything up, including you.", reflectionArabic: "يقيم كل شيء، وأنت منه."),
        DivineName(id: "al-wajid", arabic: "الْوَاجِدُ", transliteration: "Al-Wajid", meaning: "The Finder", verse: "", meaningArabic: "الغني الذي لا يعوزه شيء", reflectionEnglish: "Nothing you need is out of His reach.", reflectionArabic: "لا شيء تحتاجه بعيد عنه."),
        DivineName(id: "al-majid-2", arabic: "الْمَاجِدُ", transliteration: "Al-Majid", meaning: "The Noble", verse: "", meaningArabic: "الكريم الواسع الفضل", reflectionEnglish: "Noble in how He treats those who fall.", reflectionArabic: "كريم في معاملة من سقط."),
        DivineName(id: "al-wahid", arabic: "الْوَاحِدُ", transliteration: "Al-Wahid", meaning: "The One", verse: "13:16", meaningArabic: "الواحد الذي لا شريك له", reflectionEnglish: "One direction to turn: simple, and enough.", reflectionArabic: "وجهة واحدة تتجه إليها، وكفى."),
        DivineName(id: "al-ahad", arabic: "الْأَحَدُ", transliteration: "Al-Ahad", meaning: "The Unique", verse: "112:1", meaningArabic: "الأحد في ذاته وصفاته", reflectionEnglish: "There is no one like Him, so compare Him to no one.", reflectionArabic: "لا مثيل له، فلا تقسه بأحد."),
        DivineName(id: "as-samad", arabic: "الصَّمَدُ", transliteration: "As-Samad", meaning: "The Eternal Refuge", verse: "112:2", meaningArabic: "الذي يُقصد في الحاجات", reflectionEnglish: "The One everyone leans on, who leans on no one.", reflectionArabic: "الذي يقصده الجميع ولا يحتاج أحدًا."),
        DivineName(id: "al-qadir", arabic: "الْقَادِرُ", transliteration: "Al-Qadir", meaning: "The All-Able", verse: "6:65", meaningArabic: "القادر على كل شيء", reflectionEnglish: "Able to change your situation tonight.", reflectionArabic: "قادر على تغيير حالك الليلة."),
        DivineName(id: "al-muqtadir", arabic: "الْمُقْتَدِرُ", transliteration: "Al-Muqtadir", meaning: "The Omnipotent", verse: "18:45", meaningArabic: "صاحب القدرة المطلقة", reflectionEnglish: "Nothing is impossible for Him.", reflectionArabic: "لا مستحيل عنده."),
        DivineName(id: "al-muqaddim", arabic: "الْمُقَدِّمُ", transliteration: "Al-Muqaddim", meaning: "The Expediter", verse: "", meaningArabic: "الذي يقدّم من يشاء", reflectionEnglish: "What comes early comes by His timing.", reflectionArabic: "ما جاء مبكرًا جاء بتوقيته."),
        DivineName(id: "al-muakhkhir", arabic: "الْمُؤَخِّرُ", transliteration: "Al-Mu’akhkhir", meaning: "The Delayer", verse: "", meaningArabic: "الذي يؤخر من يشاء", reflectionEnglish: "A delay from Him is not a denial.", reflectionArabic: "تأخيره ليس حرمانًا."),
        DivineName(id: "al-awwal", arabic: "الْأَوَّلُ", transliteration: "Al-Awwal", meaning: "The First", verse: "57:3", meaningArabic: "الذي ليس قبله شيء", reflectionEnglish: "Before your worry existed, He was.", reflectionArabic: "كان قبل أن يوجد همّك."),
        DivineName(id: "al-akhir", arabic: "الْآخِرُ", transliteration: "Al-Akhir", meaning: "The Last", verse: "57:3", meaningArabic: "الذي ليس بعده شيء", reflectionEnglish: "After your worry is gone, He remains.", reflectionArabic: "يبقى بعد زوال همّك."),
        DivineName(id: "az-zahir", arabic: "الظَّاهِرُ", transliteration: "Az-Zahir", meaning: "The Manifest", verse: "57:3", meaningArabic: "الظاهر بآياته فوق كل شيء", reflectionEnglish: "His signs are everywhere you look.", reflectionArabic: "آياته في كل ما تنظر إليه."),
        DivineName(id: "al-batin", arabic: "الْبَاطِنُ", transliteration: "Al-Batin", meaning: "The Hidden", verse: "57:3", meaningArabic: "القريب الذي لا تدركه الأبصار", reflectionEnglish: "Closer than what you can see.", reflectionArabic: "أقرب مما ترى."),
        DivineName(id: "al-wali", arabic: "الْوَالِي", transliteration: "Al-Wali", meaning: "The Governor", verse: "13:11", meaningArabic: "المتولي لأمور الخلق", reflectionEnglish: "He runs the affairs you are losing sleep over.", reflectionArabic: "يدبّر الأمور التي تسهر لأجلها."),
        DivineName(id: "al-mutaali", arabic: "الْمُتَعَالِي", transliteration: "Al-Muta‘ali", meaning: "The Most Exalted", verse: "13:9", meaningArabic: "المتعالي عن كل نقص", reflectionEnglish: "Exalted above every limitation.", reflectionArabic: "متعالٍ عن كل قصور."),
        DivineName(id: "al-barr", arabic: "الْبَرُّ", transliteration: "Al-Barr", meaning: "The Source of Goodness", verse: "52:28", meaningArabic: "المحسن إلى عباده", reflectionEnglish: "Kindness comes from Him first.", reflectionArabic: "الإحسان منه أولًا."),
        DivineName(id: "at-tawwab", arabic: "التَّوَّابُ", transliteration: "At-Tawwab", meaning: "The Acceptor of Repentance", verse: "2:37", meaningArabic: "الذي يقبل التوبة ويعين عليها", reflectionEnglish: "He turns to you before you turn to Him.", reflectionArabic: "يقبل عليك قبل أن تقبل عليه."),
    ]
    private static let names5: [DivineName] = [
        DivineName(id: "al-muntaqim", arabic: "الْمُنْتَقِمُ", transliteration: "Al-Muntaqim", meaning: "The Avenger", verse: "32:22", meaningArabic: "الذي ينتقم من الظالمين", reflectionEnglish: "Justice will come; it is not yours to carry.", reflectionArabic: "العدل آتٍ وليس عليك حمله."),
        DivineName(id: "al-afuww", arabic: "الْعَفُوُّ", transliteration: "Al-‘Afuww", meaning: "The Pardoner", verse: "4:43", meaningArabic: "الذي يمحو الذنوب", reflectionEnglish: "He erases, not just forgives.", reflectionArabic: "يمحو الذنب لا يغفره فقط."),
        DivineName(id: "ar-rauf", arabic: "الرَّءُوفُ", transliteration: "Ar-Ra’uf", meaning: "The Most Kind", verse: "2:143", meaningArabic: "شديد الرحمة والرأفة", reflectionEnglish: "Tender with you when you are hardest on yourself.", reflectionArabic: "رؤوف بك حين تقسو على نفسك."),
        DivineName(id: "malik-ul-mulk", arabic: "مَالِكُ الْمُلْكِ", transliteration: "Malik-ul-Mulk", meaning: "Owner of All Sovereignty", verse: "3:26", meaningArabic: "مالك الملك كله", reflectionEnglish: "Every kingdom, every boss, every system: His.", reflectionArabic: "كل ملك وكل سلطة له."),
        DivineName(id: "dhul-jalali-wal-ikram", arabic: "ذُو الْجَلَالِ وَالْإِكْرَامِ", transliteration: "Dhul-Jalali wal-Ikram", meaning: "Lord of Majesty and Honour", verse: "55:27", meaningArabic: "صاحب الجلال والإكرام", reflectionEnglish: "Awe and generosity in the same Name.", reflectionArabic: "الجلال والكرم في اسم واحد."),
        DivineName(id: "al-muqsit", arabic: "الْمُقْسِطُ", transliteration: "Al-Muqsit", meaning: "The Equitable", verse: "3:18", meaningArabic: "العادل في حكمه", reflectionEnglish: "He settles every account fairly.", reflectionArabic: "يقضي في كل حساب بالقسط."),
        DivineName(id: "al-jami", arabic: "الْجَامِعُ", transliteration: "Al-Jami‘", meaning: "The Gatherer", verse: "3:9", meaningArabic: "الذي يجمع الخلق ليوم لا ريب فيه", reflectionEnglish: "He gathers what was scattered.", reflectionArabic: "يجمع ما تفرّق."),
        DivineName(id: "al-ghaniyy", arabic: "الْغَنِيُّ", transliteration: "Al-Ghaniyy", meaning: "The Self-Sufficient", verse: "2:263", meaningArabic: "الغني عن كل شيء", reflectionEnglish: "He needs nothing from you, and still gives.", reflectionArabic: "لا يحتاج شيئًا منك ومع ذلك يعطي."),
        DivineName(id: "al-mughni", arabic: "الْمُغْنِي", transliteration: "Al-Mughni", meaning: "The Enricher", verse: "9:28", meaningArabic: "الذي يغني من يشاء", reflectionEnglish: "Enough, then more than enough.", reflectionArabic: "الكفاية ثم الزيادة."),
        DivineName(id: "al-mani", arabic: "الْمَانِعُ", transliteration: "Al-Mani‘", meaning: "The Preventer", verse: "", meaningArabic: "الذي يمنع ما يشاء", reflectionEnglish: "What He kept from you protected you.", reflectionArabic: "ما منعه عنك حماك."),
        DivineName(id: "ad-darr", arabic: "الضَّارُّ", transliteration: "Ad-Darr", meaning: "The Distresser", verse: "", meaningArabic: "الذي يقدّر الضر بحكمة", reflectionEnglish: "Even hardship passes through His wisdom.", reflectionArabic: "حتى الضر يمر بحكمته."),
        DivineName(id: "an-nafi", arabic: "النَّافِعُ", transliteration: "An-Nafi‘", meaning: "The Benefactor", verse: "", meaningArabic: "الذي يقدّر النفع", reflectionEnglish: "All benefit traces back to Him.", reflectionArabic: "كل نفع يعود إليه."),
        DivineName(id: "an-nur", arabic: "النُّورُ", transliteration: "An-Nur", meaning: "The Light", verse: "24:35", meaningArabic: "نور السماوات والأرض", reflectionEnglish: "Light for a heart that feels dark.", reflectionArabic: "نور لقلب يشعر بالظلمة."),
        DivineName(id: "al-hadi", arabic: "الْهَادِي", transliteration: "Al-Hadi", meaning: "The Guide", verse: "22:54", meaningArabic: "الذي يهدي من يشاء", reflectionEnglish: "Ask Him for the way; He shows it.", reflectionArabic: "اسأله الطريق يُرِكَه."),
        DivineName(id: "al-badi", arabic: "الْبَدِيعُ", transliteration: "Al-Badi‘", meaning: "The Incomparable Originator", verse: "2:117", meaningArabic: "المبدع بلا مثال سابق", reflectionEnglish: "He creates without a template; He can create a way out.", reflectionArabic: "يبدع بلا مثال سابق، ويبدع لك مخرجًا."),
        DivineName(id: "al-baqi", arabic: "الْبَاقِي", transliteration: "Al-Baqi", meaning: "The Everlasting", verse: "55:27", meaningArabic: "الباقي الذي لا يفنى", reflectionEnglish: "When everything fades, He stays.", reflectionArabic: "حين يزول كل شيء، يبقى هو."),
        DivineName(id: "al-warith", arabic: "الْوَارِثُ", transliteration: "Al-Warith", meaning: "The Inheritor", verse: "15:23", meaningArabic: "الذي يرث الأرض ومن عليها", reflectionEnglish: "Everything returns to Him in the end.", reflectionArabic: "إليه يرجع كل شيء في النهاية."),
        DivineName(id: "ar-rashid", arabic: "الرَّشِيدُ", transliteration: "Ar-Rashid", meaning: "The Guide to the Right Path", verse: "", meaningArabic: "المرشد إلى الصواب", reflectionEnglish: "His guidance is never a wrong turn.", reflectionArabic: "إرشاده لا يضل أبدًا."),
        DivineName(id: "as-sabur", arabic: "الصَّبُورُ", transliteration: "As-Sabur", meaning: "The Patient", verse: "", meaningArabic: "الذي لا يعجل على العصاة", reflectionEnglish: "He waits for you. Come back.", reflectionArabic: "ينتظرك، فعُد."),
    ]
}
